import collectd
import requests
import json

SUMO_LOGIC_URL = 'https://endpoint.sumologic.com/receiver/v1/http/carbon'

def configure_callback(conf):
    for node in conf.children:
        key = node.key.lower()
        val = node.values[0]
        if key == 'sumo_logic_url':
            global SUMO_LOGIC_URL
            SUMO_LOGIC_URL = val
        else:
            collectd.warning('Unknown config key: %s.' % key)

def write_callback(value, data=None):
    metric = {
        'timestamp': int(collectd.time()),
        'plugin': data.plugin,
        'plugin_instance': data.plugin_instance,
        'type': data.type,
        'type_instance': data.type_instance,
        'values': [value],
    }
    headers = {
        'Content-Type': 'application/json',
    }
    try:
        response = requests.post(SUMO_LOGIC_URL, data=json.dumps([metric]), headers=headers)
        if response.status_code != 200:
            collectd.warning('Failed to send metric to Sumo Logic: %s' % response.text)
    except requests.exceptions.RequestException as e:
        collectd.warning('Failed to send metric to Sumo Logic: %s' % str(e))

collectd.register_config(configure_callback)
collectd.register_write(write_callback)

