        try:
            response = self.qldb.describe_ledger(Name=self.ledger_name)
            print(f"Described ledger with name {self.ledger_name}")
            return response
        except Exception as e:
            print(e)

    def update_ledger(self, new_ledger_name):
        try:
            response = self.qldb.update_ledger(Name=self.ledger_name, Attributes={'Name': new_ledger_name})
            print(f"Updated ledger from {self.ledger_name} to {new_ledger_name}")
            self.ledger_name = new_ledger_name
            return response
        except Exception as e:
            print(e)

