                print(f"Document with id {document['id']} already exists")
            else:
                self.qldb.start_transaction(LedgerName=self.ledger_name, TransactionId='1')
                self.qldb.append_page(
                    LedgerName=self.ledger_name,
                    TransactionId='1',
                    Page={
                        'TableName': table_name,
                        'Items': [document]
                    }
                )
                self.qldb.commit_transaction(
                    LedgerName=self.ledger_name,
                    TransactionId='1'
