class AutoApiDocSphinx:
    def __init__(self, builder):
        self.builder = builder

    def run(self):
        app = self.builder.app
        env = app.env
        srcdir = os.path.abspath(app.srcdir)
        apidoc_path = os.path.join(srcdir, 'apidoc')

        # Remove old API doc if exists
        if os.path.exists(apidoc_path):
            shutil.rmtree(apidoc_path)

        # Run sphinx-apidoc
        subprocess.run(['sphinx-apidoc', '-o', apidoc_path, srcdir], check=True)

        # Add the new files to the environment
        for filename in os.listdir(apidoc_path):
            if filename.endswith('.rst'):
                env.note_dependency(os.path.join(apidoc_path, filename))

        # Inject the generated files into the ToC
        app.env.todo = set()
        for root, dirs, files in os.walk(apidoc_path):
            for file in files:
                if file.endswith('.rst'):
                    docname = os.path.relpath(os.path.join(root, file), srcdir)
                    app.env.todo.add(docname)

def setup(app):
    app.connect('builder-inited', AutoApiDocSphinx(app.builder).run)

