import boto3
from dateutil import parser

def parse_logs(log_events):
    cron_jobs = {}
    for log_event in log_events:
        message = log_event['message']
        # Parse the message assuming it's a JSON string
        try:
            job_info = eval(message)
            cron_expression = job_info['cron_expression']
            timestamp = parser.parse(job_info['timestamp'])
            cron_jobs[cron_expression] = timestamp
        except Exception as e:
            print(f"Failed to parse log event: {log_event}, error: {e}")
    return cron_jobs

def fetch_logs(log_group_name, query_string):
    client = boto3.client('logs')
    response = client.start_query(
        logGroupName=log_group_name,
        queryString=query_string,
    )
    query_id = response['queryId']
    # Wait for the query to complete
    while True:
        response = client.get_query_results(queryId=query_id)
        status = response['status']
        if status['state'] == 'Complete':
            return parse_logs(response['results'])
        elif status['state'] == 'Failed':
            raise Exception(f"Query failed with error: {status['errorMessage']}")
        # Wait before fetching the next batch of results
        time.sleep(1)

def main():
    log_group_name = 'your_log_group_name'
    query_string = 'your_query_string'
    cron_jobs = fetch_logs(log_group_name, query_string)
    for cron_expression, timestamp in cron_jobs.items():
        print(f"Cron expression: {cron_expression}, Last executed: {timestamp.strftime('%Y-%m-%d %H:%M:%S')}")

if __name__ == "__main__":
    main()

import boto3
from dateutil import parser

def parse_cloudwatch_logs(log_events):
    cron_expressions = {}
    for log_event in log_events:
        message = log_event['message']
        timestamp = parser.parse(log_event['timestamp'])
        if "cron(" in message:
            start = message.find("cron(") + 5
            end = message.find(")", start)
            cron_expression = message[start:end]
            cron_expressions[cron_expression] = timestamp
    return cron_expressions

def format_cron_expressions(cron_expressions):
    for cron_expression, timestamp in cron_expressions.items():
        print(f"Cron Expression: {cron_expression}")
        print(f"Last Executed: {timestamp.strftime('%Y-%m-%d %H:%M:%S')}\n")

def get_logs(log_group_name, log_stream_name):
    client = boto3.client('logs')
    response = client.get_log_events(
        logGroupName=log_group_name,
        logStreamName=log_stream_name
    )
    return response['events']

