from flask import Flask, request, Response
from requests_ntlm import HttpNtlmAuth
import requests

app = Flask(__name__)

@app.route('/proxy', methods=['GET', 'POST', 'PUT', 'DELETE'])
def proxy():
    url = request.url.replace('http://localhost:5000', 'http://destination.com')
    method = request.method

    headers = dict(request.headers)
    headers.pop('Host', None)
    headers.pop('Content-Length', None)

    data = request.get_data()

    if 'Authorization' in headers:
        headers['Authorization'] = headers['Authorization'].replace('NTLM ', '')

    if method == 'GET':
        resp = requests.get(url, headers=headers, auth=HttpNtlmAuth('username', 'password'))
    elif method == 'POST':
        resp = requests.post(url, headers=headers, data=data, auth=HttpNtlmAuth('username', 'password'))
    elif method == 'PUT':
        resp = requests.put(url, headers=headers, data=data, auth=HttpNtlmAuth('username', 'password'))
    elif method == 'DELETE':
        resp = requests.delete(url, headers=headers, auth=HttpNtlmAuth('username', 'password'))
    else:
        return Response(status=501)

    # Convert response to Flask response
    return app.response_class(
        resp.content,
        resp.status_code,
        resp.headers.items()
    )

if __name__ == '__main__':
    app.run(port=5000)
